export const scripts: string[] = ["\n    function switchTab(tabType) {\n      const tabHealth = document.getElementById('tab-health');\n      const tabMotor = document.getElementById('tab-motor');\n      const tabLoan = document.getElementById('tab-loan');\n      const dynamicLabel = document.getElementById('dynamicLabel');\n      const dynamicField = document.getElementById('dynamicField');\n\n      [tabHealth, tabMotor, tabLoan].forEach(btn => {\n        btn.className = 'flex-1 py-2 text-center text-xs sm:text-sm font-medium rounded-lg text-slate-600 hover:text-[#0D2C54] transition-all';\n      });\n\n      if (tabType === 'health') {\n        tabHealth.className = 'flex-1 py-2 text-center text-xs sm:text-sm font-semibold rounded-lg bg-white text-[#0D2C54] shadow-sm border border-slate-200/50 transition-all';\n        dynamicLabel.innerText = 'Select Insurance Requirement';\n        dynamicField.innerHTML = `\n          <option value=\"Comprehensive Family Floater (\u20b910L - \u20b91 Crore)\">Comprehensive Family Floater (\u20b910L - \u20b91 Crore)</option>\n          <option value=\"Senior Citizens & Parents (Above 60 Yrs)\">Senior Citizens &amp; Parents (Above 60 Yrs)</option>\n          <option value=\"Cashless Maternity & Day-1 Newborn Cover\">Cashless Maternity &amp; Day-1 Newborn Cover</option>\n          <option value=\"Super Top-Up High Cover Plan\">Super Top-Up Plan (\u20b925L / \u20b950L Shield)</option>\n        `;\n      } else if (tabType === 'motor') {\n        tabMotor.className = 'flex-1 py-2 text-center text-xs sm:text-sm font-semibold rounded-lg bg-white text-[#0D2C54] shadow-sm border border-slate-200/50 transition-all';\n        dynamicLabel.innerText = 'Vehicle Insurance Type';\n        dynamicField.innerHTML = `\n          <option value=\"Car - Zero Depreciation (Bumper-to-Bumper)\">Car - Zero Depreciation (Bumper-to-Bumper)</option>\n          <option value=\"Two Wheeler Comprehensive Renewal\">Two Wheeler Comprehensive Renewal</option>\n          <option value=\"Commercial Vehicle / Fleet Shield\">Commercial Vehicle / Fleet Shield</option>\n          <option value=\"NCB Transfer Assistance (Save Up to 50%)\">NCB Transfer Assistance (Save Up to 50%)</option>\n        `;\n      } else if (tabType === 'loan') {\n        tabLoan.className = 'flex-1 py-2 text-center text-xs sm:text-sm font-semibold rounded-lg bg-white text-[#0D2C54] shadow-sm border border-slate-200/50 transition-all';\n        dynamicLabel.innerText = 'Financial Solution';\n        dynamicField.innerHTML = `\n          <option value=\"Pure Term Life \u20b91 Crore Protection\">Pure Term Life \u20b91 Crore Protection (Sec 80C)</option>\n          <option value=\"Instant Personal Loan (Salaried / Business)\">Instant Personal Loan Solutions</option>\n          <option value=\"Retirement Pension & Annuity Plan\">Retirement Pension &amp; Guaranteed Annuity Plan</option>\n          <option value=\"Critical Illness Comprehensive Shield\">Critical Illness Comprehensive Shield</option>\n        `;\n      }\n    }\n\n    function handleQuoteSubmit(e) {\n      e.preventDefault();\n      const name = document.getElementById('quoteName').value;\n      const phone = document.getElementById('quotePhone').value;\n      const plan = document.getElementById('dynamicField').value;\n      const location = document.getElementById('quoteLocation').value;\n\n      const message = `Hello Deeksha Insurance and Financial Services,%0A%0AI would like a quotation from your Chennai desk:%0A\u2022 Name: ${encodeURIComponent(name)}%0A\u2022 WhatsApp: ${encodeURIComponent(phone)}%0A\u2022 Plan: ${encodeURIComponent(plan)}%0A\u2022 Location: ${encodeURIComponent(location)}%0A%0APlease send plan comparison & premium details.`;\n      \n      window.open(`https://wa.me/916374423164?text=${message}`, '_blank');\n    }\n  "];
